package com.greenocean.backend;

import com.greenocean.backend.community.service.*;
import com.greenocean.backend.community.dto.CreateCommunityEventRequest;
import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.moderation.dto.CreateReportRequest;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseM3ActivitiesTest extends PhaseLFixtures {
 @Autowired GroupActivities activities;@Autowired GroupMemberships memberships;@Autowired GroupSafety safety;
 @Autowired com.greenocean.backend.moderation.repository.AdminRepository admin;
 UUID group(Member owner,String privacy){UUID id=UUID.randomUUID();db.update("INSERT INTO communities(id,name,slug,privacy_type,created_by) VALUES(?,?,?,?,?)",id,"Synthetic M3 "+id,"g-"+id,privacy,owner.id());db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'OWNER',1)",id,owner.id());db.update("INSERT INTO community_rules(community_id,position,rule_text) VALUES(?,1,'Protect privacy')",id);return id;}
 CreateCommunityEventRequest input(int capacity){return new CreateCommunityEventRequest("Text reflection","Share an experience without giving treatment","TEXT_CIRCLE",Instant.now().plusSeconds(86400),Instant.now().plusSeconds(90000),capacity);}
 String groupPost(Member actor,UUID group,String body)throws Exception{var in=payload(body,true);in.put("visibility","COMMUNITY");in.put("communityId",group.toString());return submit("/api/v1/posts",actor,in,201).path("id").asText();}
 void staff(Member actor){db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='MODERATOR' ON CONFLICT DO NOTHING",actor.id());}
 @Test @Tag("happy") void scheduleEditAttendAndCancelHaveNoRosterOrTransport()throws Exception{var owner=member();var reader=member();UUID g=group(owner,"PUBLIC");memberships.join(g,reader.id(),1);UUID e=activities.save(g,owner.id(),null,0,input(2));activities.attendance(g,e,reader.id(),true);activities.attendance(g,e,reader.id(),true);var details=read("/api/v1/communities/"+g+"/details",reader);assertThat(details.path("members").isEmpty()).isTrue();assertThat(details.path("events").get(0).path("attendeeCount").asInt()).isEqualTo(1);activities.save(g,owner.id(),e,1,input(3));assertThatThrownBy(()->activities.save(g,owner.id(),e,1,input(3))).isInstanceOf(ConflictException.class);activities.transition(g,e,owner.id(),2,"CANCELLED");assertThatThrownBy(()->activities.attendance(g,e,reader.id(),true)).isInstanceOf(ConflictException.class);activities.attendance(g,e,reader.id(),false);}
 @Test @Tag("malicious") void hiddenEventAndReportingIdentifiersDoNotConfirmExistence()throws Exception{var owner=member();var outsider=member();UUID g=group(owner,"HIDDEN"),e=activities.save(g,owner.id(),null,0,input(2));mvc.perform(put("/api/v1/communities/"+g+"/events/"+e+"/attendance").header("Authorization","Bearer "+outsider.token())).andExpect(status().isNotFound());submit("/api/v1/reports",outsider,Map.of("targetType","COMMUNITY","targetId",g,"reason","OTHER"),404);submit("/api/v1/reports",outsider,Map.of("targetType","EVENT","targetId",e,"reason","OTHER"),404);}
 @Test @Tag("confused") void unsupportedTransportPastTimesAndPrematureCompletionFail()throws Exception{var owner=member();UUID g=group(owner,"PUBLIC");var in=input(2);assertThatThrownBy(()->activities.save(g,owner.id(),null,0,new CreateCommunityEventRequest("Video",null,"VIDEO",in.startsAt(),in.endsAt(),2))).isInstanceOf(IllegalArgumentException.class);UUID e=activities.save(g,owner.id(),null,0,in);db.update("UPDATE community_events SET format='VIDEO' WHERE id=?",e);var prompt=payload("Historical video metadata is not a discussion service",true);prompt.put("visibility","COMMUNITY");prompt.put("communityId",g.toString());submit("/api/v1/communities/"+g+"/events/"+e+"/discussion",owner,Map.of("revision",1,"post",prompt),409);assertThatThrownBy(()->activities.transition(g,e,owner.id(),1,"COMPLETED")).isInstanceOf(ConflictException.class);db.update("UPDATE community_events SET starts_at=CURRENT_TIMESTAMP-INTERVAL '1 hour',ends_at=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE id=?",e);activities.transition(g,e,owner.id(),1,"COMPLETED");}
 @Test @Tag("malicious") void memberCannotCreateAndUnsafeMetadataCannotSkipSafety()throws Exception{var owner=member();var reader=member();UUID g=group(owner,"PUBLIC");memberships.join(g,reader.id(),1);assertThatThrownBy(()->activities.save(g,reader.id(),null,0,input(2))).isInstanceOf(ForbiddenException.class);var in=input(2);assertThatThrownBy(()->activities.save(g,owner.id(),null,0,new CreateCommunityEventRequest("I will kill you",null,"TEXT_CIRCLE",in.startsAt(),in.endsAt(),2))).isInstanceOf(ConflictException.class);}
 @Test @Tag("happy") void hostDiscussionUsesExactGroupAndPhaseLSafety()throws Exception{var owner=member();UUID g=group(owner,"HIDDEN"),e=activities.save(g,owner.id(),null,0,input(2));var in=payload("A shared text reflection",true);in.put("visibility","COMMUNITY");in.put("communityId",g.toString());submit("/api/v1/communities/"+g+"/events/"+e+"/discussion",owner,Map.of("revision",1,"post",in),200);assertThat(db.queryForObject("SELECT discussion_post_id IS NOT NULL FROM community_events WHERE id=?",Boolean.class,e)).isTrue();submit("/api/v1/communities/"+g+"/events/"+e+"/discussion",owner,Map.of("revision",2,"post",in),409);}
 @Test @Tag("malicious") void removalCancelsHostedActivitiesAndAttendance()throws Exception{var owner=member();var host=member();UUID g=group(owner,"PUBLIC");memberships.join(g,host.id(),1);db.update("UPDATE community_members SET role='MODERATOR' WHERE community_id=? AND user_id=?",g,host.id());UUID e=activities.save(g,host.id(),null,0,input(2));activities.attendance(g,e,host.id(),true);memberships.remove(g,host.id(),owner.id(),"REMOVE","Synthetic host removal",null);assertThat(db.queryForObject("SELECT status FROM community_events WHERE id=?",String.class,e)).isEqualTo("CANCELLED");assertThat(db.queryForObject("SELECT count(*) FROM community_event_attendees WHERE event_id=?",Integer.class,e)).isZero();}
 @Test @Tag("happy") void independentGroupHideAndPlatformAppealDoNotOverrideGlobalBlocks()throws Exception{var owner=member();var author=member();var reporter=member();var reviewer=member();staff(reviewer);UUID g=group(owner,"PUBLIC");memberships.join(g,author.id(),1);memberships.join(g,reporter.id(),1);UUID post=UUID.fromString(groupPost(author,g,"A permitted synthetic group story"));UUID report=safety.report(g,reporter.id(),new CreateReportRequest("POST",post,"OTHER","Please review against group boundaries"));assertThat(safety.queue(g,owner.id()).toString()).doesNotContain(author.id().toString(),author.email(),reporter.id().toString());safety.hide(g,report,owner.id(),1,"Group-specific boundary");mvc.perform(get("/api/v1/posts/"+post).header("Authorization","Bearer "+reporter.token())).andExpect(status().isNotFound());UUID action=(UUID)safety.actions(author.id()).getFirst().get("id");UUID appeal=safety.appeal(author.id(),action,"Please review this boundary independently");staff(owner);assertThatThrownBy(()->safety.decideAppeal(owner.id(),appeal,true,"Self review")).isInstanceOf(ForbiddenException.class);db.update("UPDATE posts SET status='HIDDEN' WHERE id=?",post);safety.decideAppeal(reviewer.id(),appeal,true,"Group restriction removed; global policy remains");mvc.perform(get("/api/v1/posts/"+post).header("Authorization","Bearer "+reporter.token())).andExpect(status().isNotFound());assertThat(read("/api/v1/account/archive",author).path("groupGovernance").toString()).contains("Group-specific boundary");}
 @Test @Tag("malicious") void groupActionsCannotHideRevisedOrOwnContentAndAppealsAreOwnerScoped()throws Exception{var owner=member();var author=member();UUID g=group(owner,"PUBLIC");memberships.join(g,author.id(),1);UUID post=UUID.fromString(groupPost(author,g,"Current synthetic evidence"));UUID report=safety.report(g,owner.id(),new CreateReportRequest("POST",post,"OTHER",null));assertThatThrownBy(()->safety.hide(g,report,owner.id(),1,"Own report")).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->safety.appeal(owner.id(),UUID.randomUUID(),"Guessed action")).isInstanceOf(NotFoundException.class);}
 @Test @Tag("malicious") void ownerAbuseReportsNeverReachReportedManagers()throws Exception{var owner=member();var reporter=member();UUID g=group(owner,"PUBLIC");memberships.join(g,reporter.id(),1);UUID report=safety.report(g,reporter.id(),new CreateReportRequest("USER",owner.id(),"HARASSMENT","Manager behavior"));assertThat(safety.queue(g,owner.id())).isEmpty();assertThatThrownBy(()->safety.hide(g,report,owner.id(),1,"Resolve own misconduct")).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("happy") void closureStopsPendingGrantsAndKeepsHiddenPrivacy()throws Exception{var owner=member();var target=member();UUID g=group(owner,"HIDDEN"),e=activities.save(g,owner.id(),null,0,input(2));UUID invite=(UUID)memberships.invite(g,owner.id(),target.id(),UUID.randomUUID()).get("id");safety.lifecycle(g,owner.id(),"ARCHIVED","Owner requested closure",false);assertThat(db.queryForObject("SELECT status FROM community_invitations WHERE id=?",String.class,invite)).isEqualTo("REVOKED");assertThat(db.queryForObject("SELECT privacy_type FROM communities WHERE id=?",String.class,g)).isEqualTo("HIDDEN");assertThatThrownBy(()->memberships.invitation(invite,target.id(),"ACCEPT",1)).isInstanceOf(ConflictException.class);assertThat(db.queryForObject("SELECT status FROM community_events WHERE id=?",String.class,e)).isEqualTo("CANCELLED");}
 @Test @Tag("malicious") void platformStatusRequiresRealMfaAndOrdinaryManagersCannotReadStaffEvidence()throws Exception{var owner=member();var operator=member();staff(operator);var signed=mvc.perform(post("/api/v1/auth/login").contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("email",operator.email(),"password","Synthetic L passphrase 2026")))).andExpect(status().isOk()).andReturn();String staffToken=json.readTree(signed.getResponse().getContentAsString()).path("accessToken").asText();UUID g=group(owner,"PUBLIC");mvc.perform(get("/api/v1/communities/"+g+"/details").header("Authorization","Bearer "+staffToken)).andExpect(status().isNotFound());mvc.perform(get("/api/v1/admin/groups/reports?purpose=SAFETY_REVIEW").header("Authorization","Bearer "+staffToken)).andExpect(status().isForbidden());submit("/api/v1/admin/groups/"+g+"/status",owner,Map.of("status","SUSPENDED","reason","Synthetic request"),403);mvc.perform(get("/api/v1/admin/groups/reports?purpose=SAFETY_REVIEW").header("Authorization","Bearer "+owner.token())).andExpect(status().isForbidden());}
 @Test @Tag("happy") void hiddenGovernanceReportAppealsRequireIndependentPurposeReview()throws Exception{var owner=member();var reporter=member();var reviewer=member();var independent=member();staff(reviewer);staff(independent);UUID g=group(owner,"HIDDEN");db.update("INSERT INTO community_members(community_id,user_id,rules_version_ack) VALUES(?,?,1)",g,reporter.id());UUID report=safety.report(g,reporter.id(),new CreateReportRequest("COMMUNITY",g,"OTHER","Synthetic sensitive governance context"));assertThat(safety.staffQueue(reviewer.id(),"SAFETY_REVIEW").toString()).contains(report.toString());assertThat(admin.dashboard().reports().toString()).doesNotContain("Synthetic sensitive governance context");safety.resolveReport(reviewer.id(),report,"RESOLVED","Synthetic initial review");UUID appeal=UUID.fromString(submit("/api/v1/moderation-appeals",reporter,Map.of("reportId",report,"reason","Synthetic independent governance appeal"),201).path("id").asText());assertThat(admin.operations().appeals().toString()).doesNotContain(appeal.toString());assertThat(safety.appeals(independent.id(),"APPEAL_REVIEW").toString()).contains(appeal.toString());assertThatThrownBy(()->admin.updateAppeal(appeal,independent.id(),"OVERTURN_APPEAL","Generic bypass")).isInstanceOf(ConflictException.class);assertThatThrownBy(()->safety.decideAppeal(reviewer.id(),appeal,true,"Original reviewer")).isInstanceOf(ForbiddenException.class);safety.decideAppeal(independent.id(),appeal,true,"Independent reconsideration recorded");assertThat(db.queryForObject("SELECT status FROM moderation_appeals WHERE id=?",String.class,appeal)).isEqualTo("OVERTURNED");assertThat(db.queryForObject("SELECT status FROM communities WHERE id=?",String.class,g)).isEqualTo("ACTIVE");}
 @Test @Tag("happy") void emptyMutationResponsesUseNoContentSoTheRealClientCanRefresh()throws Exception{var owner=member();UUID g=group(owner,"PUBLIC"),e=activities.save(g,owner.id(),null,0,input(2));mvc.perform(post("/api/v1/communities/"+g+"/events/"+e+"/status").header("Authorization","Bearer "+owner.token()).contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("revision",1,"status","CANCELLED")))).andExpect(status().isNoContent()).andExpect(content().string(""));mvc.perform(post("/api/v1/communities/"+g+"/close").header("Authorization","Bearer "+owner.token()).contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("reason","Synthetic confirmed closure")))).andExpect(status().isNoContent()).andExpect(content().string(""));assertThat(db.queryForObject("SELECT status FROM communities WHERE id=?",String.class,g)).isEqualTo("ARCHIVED");}
}
